module reference_module(input a, output y);
  assign y = ~a;
endmodule

module tb;
  reg a;
  wire y_ref;
  wire y_dut;
  integer i;
  integer errors;
  reference_module ref_i(.a(a), .y(y_ref));
  top_module dut(.a(a), .y(y_dut));
  initial begin
    errors = 0;
    for (i = 0; i < 2; i = i + 1) begin
      a = i[0];
      #1;
      if (y_dut !== y_ref) errors = errors + 1;
    end
    if (errors == 0) $display("PASS");
    else $display("Mismatches: %0d", errors);
    $finish;
  end
endmodule

module reference_module(input a, input b, output y);
  assign y = a & b;
endmodule

