  top_module dut(.a(a), .b(b), .y(y_dut));
  initial begin
    errors = 0;
    for (i = 0; i < 4; i = i + 1) begin
      a = i[0];
      b = i[1];
      #1;
      if (y_dut !== y_ref) errors = errors + 1;
    end
    if (errors == 0) $display("PASS");
    else $display("Mismatches: %0d", errors);
    $finish;
  end
endmodule

module reference_module(input sel, input a, input b, output y);
  assign y = sel ? b : a;
endmodule

