  reg b;
  wire y_ref;
  wire y_dut;
  integer i;
  integer errors;
  reference_module ref_i(.sel(sel), .a(a), .b(b), .y(y_ref));
  top_module dut(.sel(sel), .a(a), .b(b), .y(y_dut));
